import React from "react";
import { Box, Typography, Paper } from "@mui/material";

const UserDashboard = ({ user }) => {
  return (
    <Box sx={{ p: 4 }}>
      <Paper sx={{ p: 4, borderRadius: 3 }}>
        <Typography variant="h4" sx={{ fontWeight: 700, color: "#2E7D32" }}>
          User Dashboard
        </Typography>

        <Typography sx={{ mt: 2 }}>
          Welcome, {user.name}
        </Typography>

        <Typography sx={{ mt: 1 }}>
          Mobile: {user.mobile}
        </Typography>
      </Paper>
    </Box>
  );
};

export default UserDashboard;
